(function (){document.addEventListener("DOMContentLoaded",() =>{const yearEl = document.getElementById("current-year");if (yearEl) yearEl.textContent = new Date().getFullYear();if (window.Alpine){document.addEventListener("alpine:init",() =>{Alpine.data("helpSystem",() => ({open:false,toggle(){this.open = !this.open;},}));});}const newsletterForm = document.querySelector('form[action*="newsletter"]');if (newsletterForm){const feedback = newsletterForm.querySelector('.form-feedback');if (feedback) feedback.setAttribute('aria-live','polite');}});})();